select lives_ok($$select public.attach_map_artwork_version('44000000-0000-4000-8000-000000000001',null,0,'44000000-0000-4000-8000-000000000003','Original','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',jsonb_build_object('x',1,'y',0,'width',6,'height',6,'pixelWidth',8,'pixelHeight',8,'size',68,'mime','image/png','digest',repeat('a',64),'object_id','44000000-0000-4000-8000-000000000003','registration','forged'),jsonb_build_object('x',1,'y',0,'width',6,'height',6,'pixelWidth',8,'pixelHeight',8,'size',68,'mime','image/png','digest',repeat('c',64),'object_id','44000000-0000-4000-8000-000000000005'),'Private prompt','first')$$,'duplicate attachment reconciles same accepted version');
