select throws_ok($$select public.attach_server_map_artwork_version('00000000-0000-4000-8000-000000000001','44000000-0000-4000-8000-000000000001','44000000-0000-4000-8000-000000000003',4,'44000000-0000-4000-8000-000000000019','44000000-0000-4000-8000-000000000018','revised','Bad structural fixture','{"columns":9,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}',jsonb_build_object('x',1,'y',0,'width',6,'height',6,'pixelWidth',8,'pixelHeight',8,'size',68,'mime','image/png','digest',repeat('d',64),'object_id','44000000-0000-4000-8000-000000000019'),null,'Invalid geometry',true)$$,'P0001','Constrained result changed canonical geometry','server constrained flag cannot bypass canonical geometry');
